export type DisasterType =
  | 'Earthquake'
  | 'Flood'
  | 'Cyclone'
  | 'Wildfire'
  | 'Volcanic Eruption'
  | 'Tsunami'
  | 'Landslide'
  | 'Tornado'
  | 'Drought'
  | 'Industrial'
  | 'Other';

export type GlobalDisaster = {
  id: string;
  name: string;
  year: number;
  date?: string;
  location: string;
  country: string;
  region?: string;
  type: DisasterType;
  image: string;
  magnitude?: string;
  deaths: string;
  affected?: string;
  economicLoss?: string;
  cause: string;
  summary: string;
  consequences: string[];
  lessonsLearned: string[];
  sources: string[];
};

const image = (file: string) => `https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(file)}?width=1400`;
const source = (name: string) => `https://en.wikipedia.org/wiki/${name.replaceAll(' ', '_')}`;

const record = (
  id: string,
  name: string,
  year: number,
  location: string,
  country: string,
  type: DisasterType,
  deaths: string,
  cause: string,
  summary: string,
  file: string,
  options: Partial<Pick<GlobalDisaster, 'date' | 'region' | 'magnitude' | 'affected' | 'economicLoss' | 'consequences' | 'lessonsLearned' | 'sources'>> = {},
): GlobalDisaster => ({
  id,
  name,
  year,
  location,
  country,
  type,
  deaths,
  cause,
  summary,
  image: image(file),
  affected: 'Reliable figures vary by source.',
  consequences: ['Communities faced major disruption to housing, services, and livelihoods.', 'Recovery required coordinated public, community, and international action.'],
  lessonsLearned: ['Risk awareness and clear warnings save lives.', 'Resilient infrastructure and practiced emergency plans reduce cascading harm.'],
  sources: [source(name), 'https://www.emdat.be/'],
  ...options,
});

